import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, random } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type NewspaperMatchCutProps = Record<string, any>;

// A dense corpus of news-like text to generate realistic paragraphs
const rawNewsText = "Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. Ut enim ad minim veniam, quis nostrud exercitation ullamco laboris nisi ut aliquip ex ea commodo consequat. Duis aute irure dolor in reprehenderit in voluptate velit esse cillum dolore eu fugiat nulla pariatur. Excepteur sint occaecat cupidatat non proident, sunt in culpa qui officia deserunt mollit anim id est laborum. Sed ut perspiciatis unde omnis iste natus error sit voluptatem accusantium doloremque laudantium, totam rem aperiam, eaque ipsa quae ab illo inventore veritatis et quasi architecto beatae vitae dicta sunt explicabo. Nemo enim ipsam voluptatem quia voluptas sit aspernatur aut odit aut fugit, sed quia consequuntur magni dolores eos qui ratione voluptatem sequi nesciunt. Neque porro quisquam est, qui dolorem ipsum quia dolor sit amet, consectetur, adipisci velit, sed quia non numquam eius modi tempora incidunt ut labore et dolore magnam aliquam quaerat voluptatem. Ut enim ad minima veniam, quis nostrum exercitationem ullam corporis suscipit laboriosam, nisi ut aliquid ex ea commodi consequatur? Quis autem vel eum iure reprehenderit qui in ea voluptate velit esse quam nihil molestiae consequatur, vel illum qui dolorem eum fugiat quo voluptas nulla pariatur?";
const baseWords = rawNewsText.split(' ');

const generateRealisticText = (scene: number, block: string, length: number, keyword: string) => {
  const startIndex = Math.floor(random(`${scene}-${block}-start`) * baseWords.length);
  const result = [];
  for (let i = 0; i < length; i++) {
    const wordIndex = (startIndex + i) % baseWords.length;
    const word = baseWords[wordIndex];

    // Inject the keyword randomly to simulate multiple occurrences
    const r = random(`${scene}-${block}-kw-${i}`);
    if (r < 0.04) {
      result.push(keyword);
    } else if (r < 0.06) {
      result.push(keyword);
      result.push(word);
    } else {
      result.push(word);
    }
  }
  return result.join(' ');
};

const NewspaperMatchCut: React.FC<NewspaperMatchCutProps> = ({
  backgroundColor = "#f4f1ea",
  durationInSeconds = 10,
  keyword = "COVID-19",
  highlightColor = "#ffe135",
  textColor = "#1d1c1a",
  fontSize = 52,
}) => {

  useFontLoader(["Playfair Display"]);

  const frame = useCurrentFrame();
  const { width } = useVideoConfig();

  const bgColor = backgroundColor;
  const framesPerCut = 5;
  
  // Calculate which "cut" we are currently on
  const currentScene = Math.floor(frame / framesPerCut);

  // Generate deterministic text for this specific scene
  const topTextStr = useMemo(() => generateRealisticText(currentScene, 'top', 250, keyword), [currentScene, keyword]);
  const bottomTextStr = useMemo(() => generateRealisticText(currentScene, 'bottom', 250, keyword), [currentScene, keyword]);
  const prefixStr = useMemo(() => generateRealisticText(currentScene, 'prefix', 30, keyword), [currentScene, keyword]);
  const suffixStr = useMemo(() => generateRealisticText(currentScene, 'suffix', 30, keyword), [currentScene, keyword]);

  const lineHeight = 1.1;
  const heroLineHeight = fontSize * lineHeight;
  const containerWidth = "85%";

  const textStyle: React.CSSProperties = {
    fontFamily: "Playfair Display, serif",
    fontSize: `${fontSize}px`,
    lineHeight: lineHeight,
    color: textColor,
    letterSpacing: "-0.01em",
  };

  const highlightStyle: React.CSSProperties = {
    backgroundColor: highlightColor,
    color: "#000",
    padding: "0 0.1em",
    borderRadius: "2px",
    fontWeight: 700,
    mixBlendMode: "multiply",
    boxShadow: `0 0 4px 1px ${highlightColor}`,
  };

  // Extract the inner content to render it in two layered containers (sharp center vs blurred edges)
  const newspaperContent = (
    <>
      {/* Top Paragraph Block - Grows upwards from the center */}
      <div style={{
        position: "absolute",
        bottom: "50%",
        left: 0,
        right: 0,
        height: "150vh", // Generous height to ensure it fills off-screen
        marginBottom: heroLineHeight / 2,
        display: "flex",
        flexDirection: "column",
        justifyContent: "flex-end",
        overflow: "hidden",
        transition: "none"
      }}>
        <div style={{ textAlign: "justify", transition: "none" }}>
          {topTextStr}
        </div>
      </div>

      {/* Hero Line - A perfectly centered CSS Grid that clips overflowing text */}
      <div style={{
        position: "absolute",
        top: "50%",
        left: 0,
        right: 0,
        height: heroLineHeight,
        transform: "translateY(-50%)",
        display: "grid",
        gridTemplateColumns: "1fr auto 1fr",
        gap: "0.25em",
        alignItems: "center",
        transition: "none"
      }}>
        {/* Prefix Text - Aligns right, clips on the left */}
        <div style={{ display: "flex", justifyContent: "flex-end", overflow: "hidden", transition: "none" }}>
          <span style={{ whiteSpace: "nowrap", transition: "none" }}>
            {prefixStr}
          </span>
        </div>
        
        {/* THE STATIONARY HERO WORD */}
        <div style={{ display: "flex", alignItems: "center", justifyContent: "center", transition: "none" }}>
            <span style={highlightStyle}>{keyword}</span>
        </div>

        {/* Suffix Text - Aligns left, clips on the right */}
        <div style={{ display: "flex", justifyContent: "flex-start", overflow: "hidden", transition: "none" }}>
          <span style={{ whiteSpace: "nowrap", transition: "none" }}>
            {suffixStr}
          </span>
        </div>
      </div>

      {/* Bottom Paragraph Block - Grows downwards from the center */}
      <div style={{
        position: "absolute",
        top: "50%",
        left: 0,
        right: 0,
        height: "150vh",
        marginTop: heroLineHeight / 2,
        display: "flex",
        flexDirection: "column",
        justifyContent: "flex-start",
        overflow: "hidden",
        transition: "none"
      }}>
        <div style={{ textAlign: "justify", transition: "none" }}>
          {bottomTextStr}
        </div>
      </div>
    </>
  );

  return (
    <AbsoluteFill style={{ ...textStyle }}>
      
      {/* Base Background Fill */}
      <AbsoluteFill style={{ backgroundColor: bgColor }} />

      {/* Layer 1: Blurred and Enlarged (Simulating out-of-focus edges) */}
      <AbsoluteFill style={{
        transform: "scale(1.06)",
        filter: "contrast(1.1) blur(5px)",
        transition: "none"
      }}>
        <div style={{
          width: containerWidth,
          height: "100%",
          margin: "0 auto",
          position: "relative",
          transition: "none"
        }}>
          {newspaperContent}
        </div>
      </AbsoluteFill>

      {/* Layer 2: Sharp Center with Radial Mask fading at the edges */}
      <AbsoluteFill style={{
        backgroundColor: bgColor,
        filter: "contrast(1.2) blur(0.3px)", // Slight original print noise
        WebkitMaskImage: "radial-gradient(ellipse at center, rgba(0,0,0,1) 25%, rgba(0,0,0,0) 75%)",
        maskImage: "radial-gradient(ellipse at center, rgba(0,0,0,1) 25%, rgba(0,0,0,0) 75%)",
        transition: "none"
      }}>
        <div style={{
          width: containerWidth,
          height: "100%",
          margin: "0 auto",
          position: "relative",
          transition: "none"
        }}>
          {newspaperContent}
        </div>
      </AbsoluteFill>
      
      {/* Subtle vignette for macro-photography feel */}
      <AbsoluteFill style={{
        backgroundImage: 'radial-gradient(circle, transparent 60%, rgba(0,0,0,0.15) 150%)',
        pointerEvents: 'none',
        zIndex: 10
      }} />

    </AbsoluteFill>
  );
};

export default NewspaperMatchCut;